#define main legacy_main
#include "../bfs-cuda/bfs.cu"
#undef main
#include <vector>
#include <queue>
#include <string>
#include <algorithm>
struct Graph{int N;std::vector<Node>nodes;std::vector<int>edges,gold;std::vector<std::vector<int>>adj;Node*dn;int *de,*dc;char *dm,*du,*dv,*dov;Graph(int f){N=f==1?513:257;adj.resize(N);if(f==1){for(int i=0;i<=480;i++){adj[i].push_back(i);for(int j:{2*i+1,2*i+2})if(j<=480){adj[i].push_back(j);adj[i].push_back(j);}if(i>0)adj[i].push_back((i-1)/2);}for(int i=481;i<=512;i++)adj[i].push_back(481+(i-481+1)%32);}else{for(int i=1;i<=32;i++)adj[0].push_back(i);for(int i=1;i<=32;i++){adj[i].push_back(0);for(int k=0;k<8;k++)adj[i].push_back(33+((i-1)*7+k*17)%128);}for(int i=33;i<=160;i++){adj[i].push_back(i);adj[i].push_back(161+((i-33)*5)%64);adj[i].push_back(161+((i-33)*5+1)%64);}for(int i=161;i<=224;i++)adj[i].push_back(1+(i-161)%32);for(int i=225;i<=256;i++)adj[i].push_back(225+(i-225+1)%32);}for(auto&a:adj){nodes.push_back({(int)edges.size(),(int)a.size()});edges.insert(edges.end(),a.begin(),a.end());}gold.assign(N,-1);gold[0]=0;std::queue<int>q;q.push(0);while(!q.empty()){int i=q.front();q.pop();for(int j:adj[i])if(gold[j]<0){gold[j]=gold[i]+1;q.push(j);}}cudaMalloc(&dn,N*sizeof(Node));cudaMalloc(&de,edges.size()*4);cudaMalloc(&dc,N*4);cudaMalloc(&dm,N);cudaMalloc(&du,N);cudaMalloc(&dv,N);cudaMalloc(&dov,1);cudaMemcpy(dn,nodes.data(),N*sizeof(Node),cudaMemcpyHostToDevice);cudaMemcpy(de,edges.data(),edges.size()*4,cudaMemcpyHostToDevice);}
std::pair<std::vector<int>,double>run(){std::vector<char>m(N),v(N),u(N);m[0]=v[0]=1;std::vector<int>c(N,-1);c[0]=0;cudaMemcpy(dm,m.data(),N,cudaMemcpyHostToDevice);cudaMemcpy(du,u.data(),N,cudaMemcpyHostToDevice);cudaMemcpy(dv,v.data(),N,cudaMemcpyHostToDevice);cudaMemcpy(dc,c.data(),N*4,cudaMemcpyHostToDevice);double elapsed=0;int levels=0;char over;do{over=0;cudaMemcpy(dov,&over,1,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();Kernel<<<(N+255)/256,256>>>(dn,de,dm,du,dv,dc,N);Kernel2<<<(N+255)/256,256>>>(dm,du,dv,dov,N);cudaDeviceSynchronize();elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();cudaMemcpy(&over,dov,1,cudaMemcpyDeviceToHost);if(++levels>N)exit(4);}while(over);cudaMemcpy(c.data(),dc,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(v.data(),dv,N,cudaMemcpyDeviceToHost);cudaMemcpy(m.data(),dm,N,cudaMemcpyDeviceToHost);cudaMemcpy(u.data(),du,N,cudaMemcpyDeviceToHost);bool ok=c==gold&&levels==*std::max_element(gold.begin(),gold.end())+1;for(int i=0;i<N;i++)ok&=v[i]==(gold[i]>=0)&&m[i]==0&&u[i]==0;if(!ok)exit(3);for(auto*a:{&v,&m,&u})for(char x:*a)c.push_back((int)x);c.push_back(over);c.push_back(levels);return {c,elapsed};}};
int main(){Graph a(1),b(2);std::vector<Graph*>gs={&a,&b};std::vector<int>prefix;for(auto*g:gs){for(auto n:g->nodes)prefix.push_back(n.starting);for(auto n:g->nodes)prefix.push_back(n.no_of_edges);prefix.insert(prefix.end(),g->edges.begin(),g->edges.end());prefix.push_back(0);g->run();std::vector<char>m(g->N),u(g->N),v(g->N);std::vector<int>c(g->N,-1);m[0]=v[0]=1;c[0]=0;run_bfs_cpu(g->N,g->nodes.data(),g->edges.size(),g->edges.data(),m.data(),u.data(),v.data(),c.data());if(c!=g->gold)return 5;}
for(int trial=1;trial<=5;trial++){std::vector<int>got;double elapsed=0;for(auto*g:gs){auto v=g->run();got.insert(got.end(),v.first.begin(),v.first.end());elapsed+=v.second;}auto artifact=prefix;artifact.insert(artifact.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),fp);fclose(fp);bool ok=cudaGetLastError()==cudaSuccess;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"sum_all_converged_frontier_kernel_pairs_excluding_flag_transfers\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),path.c_str(),artifact.size());if(!ok)return 2;}for(auto*g:gs){cudaFree(g->dn);cudaFree(g->de);cudaFree(g->dc);cudaFree(g->dm);cudaFree(g->du);cudaFree(g->dv);cudaFree(g->dov);}}
